mapper.select:
SELECT v.id, v.biz_type, v.biz_id, v.biz_no, v.warehouse_id, w.code AS warehouse_code, w.name AS warehouse_name, v.material_id, m.code AS material_code, m.name AS material_name, v.batch_no, v.location_id, l.code AS location_code, v.qty, v.remark, v.create_time FROM inv_movement v LEFT JOIN base_warehouse w ON w.id = v.warehouse_id LEFT JOIN base_material m ON m.id = v.material_id LEFT JOIN base_location l ON l.id = v.location_id WHERE v.deleted = 0
AND v.biz_type = #{q.bizType}
AND v.create_time >= #{q.beginDate}
AND v.create_time < DATE_ADD(#{q.endDate}, INTERVAL 1 DAY)
AND v.material_id = #{q.materialId}
AND v.warehouse_id = #{q.warehouseId}
AND (v.biz_no LIKE CONCAT('%', #{q.keyword}, '%') OR m.code LIKE CONCAT('%', #{q.keyword}, '%') OR m.name LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY v.id DESC
